import{z as o,x as l,o as A,c as p,q as s,j as B,D as t,d as E,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"序号与重传","description":"","frontmatter":{"title":"序号与重传","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-seq-rexmit.md","filePath":"cs/tcp-seq-rexmit.md","lastUpdated":1791413859000}'),C={name:"cs/tcp-seq-rexmit.md"};function d(D,a,m,T,c,u){const r=l("Mermaid");return A(),p("div",null,[a[2]||(a[2]=s('<h1 id="序号与重传" tabindex="-1">序号与重传 <a class="header-anchor" href="#序号与重传" aria-label="Permalink to &quot;序号与重传&quot;">​</a></h1><div class="epigraph"><p>每个字节一个序号；累计确认告诉发送方前缀已到。丢了就按定时器或重复确认重发。</p><footer>—— 据 RFC 793；Karn and Partridge, Improving Round-Trip Estimates in Reliable Transport Protocols, 1987 整理</footer></div><p><a href="/cs/tcp-time-wait">上一课</a>同步了 ISN。IP 仍会丢包。<a href="/cs/layering-e2e">端到端</a>要求两端保证字节流。缺口是<strong>序号、累计 ACK、重传</strong>：把数据报变成可靠流的数据平面。本课不把接收窗口与拥塞窗口分开写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>载荷从 ISN+1 起编号。接收方 ACK 表示「期望的下一个字节」。丢失则发送方超时重传；RTO 必须估 RTT，估低了假重传，估高了延迟。Karn：重传段不拿来更新 RTT，避免歧义。缺口不是再握手，而是这条可靠机。</p><p>快速重传：三个重复 ACK 暗示该序号丢了，可不等 RTO。本课点名，与拥塞反应的耦合下一课之后。</p><p><span class="marginnote">累计 ACK 不描述空洞后已到达的段。SACK（RFC 2018）补上块信息，主干先掌握累计语义。</span></p><p><span class="marginnote">数字实例：发送方已发第 1 到 100 字节，接收方收到了 1 到 40 与 51 到 60，它只能回 ack=41——意思是&quot;到 40 为止全有，下一个我要 41&quot;；51 到 60 虽已到手，却不被这份 ACK 描述。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送：切段、填序号、启动该段的计时（实现常一个 RTO 时钟）。接收：按序号写入重组缓冲，交有序前缀给应用，发 ACK。重复段丢弃。校验和失败当丢。与 <a href="/cs/udp">UDP</a> 对照：UDP 把乱序交给应用；TCP 藏在内核里。</p>',10)),(A(),B(n,null,{default:t(()=>[i(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%AD%97%E8%8A%82%E5%BA%8F%E5%8F%B7%22%5D%20--%3E%20SEG%5B%22%E5%88%86%E6%AE%B5%E5%8F%91%E9%80%81%22%5D%0A%20%20SEG%20--%3E%20ACK%5B%22%E7%B4%AF%E8%AE%A1%20ACK%22%5D%0A%20%20SEG%20--%3E%20RTO%5B%22%E8%B6%85%E6%97%B6%E6%88%96%E5%BF%AB%E9%87%8D%E4%BC%A0%22%5D%0A%20%20RTO%20--%3E%20SEG%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("序号让迟到的旧连接段（若 ISN 与时间窗配合）可被拒绝；让重复可识别。重传实现端到端文件传输的「最终到」，链路 FCS 只是降丢包率。与"),e("a",{href:"/cs/ipc-pipe"},"管道"),E("对照：管道丢数据只在内核崩溃；TCP 假定中间网络会丢。")],-1)),a[5]||(a[5]=e("p",null,[E("RTO 与"),e("a",{href:"/cs/scheduling-metrics"},"调度"),E("交互：超时线程可能睡醒重发，不占 CPU 忙等。")],-1)),a[6]||(a[6]=e("p",null,"接收方每收到一个段都要做一次裁决：校验、按序提交、乱序缓存，还是丢弃重复。",-1)),(A(),B(n,null,{default:t(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%B8%80%E4%B8%AA%E6%AE%B5%E5%88%B0%E8%BE%BE%E6%8E%A5%E6%94%B6%E6%96%B9%22%5D%20--%3E%20CK%7B%22%E6%A0%A1%E9%AA%8C%E5%92%8C%E6%AD%A3%E7%A1%AE%3F%22%7D%0A%20%20CK%20--%3E%7C%22%E5%90%A6%22%7C%20DROP%5B%22%E5%BD%93%E4%BD%9C%E4%B8%A2%E5%A4%B1%2C%20%E7%9B%B4%E6%8E%A5%E4%B8%A2%E5%BC%83%22%5D%0A%20%20CK%20--%3E%7C%22%E6%98%AF%22%7C%20ORD%7B%22%E5%BA%8F%E5%8F%B7%E6%98%AF%E6%9C%9F%E6%9C%9B%E7%9A%84%E4%B8%8B%E4%B8%80%E4%B8%AA%3F%22%7D%0A%20%20ORD%20--%3E%7C%22%E6%98%AF%22%7C%20SUBMIT%5B%22%E5%86%99%E5%85%A5%E7%BC%93%E5%86%B2%2C%20%E6%8F%90%E4%BA%A4%E5%89%8D%E7%BC%80%2C%20%E5%9B%9E%20ACK%22%5D%0A%20%20ORD%20--%3E%7C%22%E5%90%A6%2C%20%E5%B7%B2%E6%94%B6%E8%BF%87%22%7C%20DUP%5B%22%E8%AF%86%E5%88%AB%E4%B8%BA%E9%87%8D%E5%A4%8D%2C%20%E4%B8%A2%E5%BC%83%22%5D%0A%20%20ORD%20--%3E%7C%22%E5%90%A6%2C%20%E7%BC%BA%E4%BA%86%E5%89%8D%E9%9D%A2%E7%9A%84%22%7C%20BUF%5B%22%E7%BC%93%E5%AD%98%E5%9C%A8%E9%87%8D%E7%BB%84%E9%98%9F%E5%88%97%22%5D%0A%20%20BUF%20--%3E%20HOLE%7B%22%E7%A9%BA%E6%B4%9E%E8%A2%AB%E8%A1%A5%E9%BD%90%3F%22%7D%0A%20%20HOLE%20--%3E%7C%22%E6%98%AF%22%7C%20SUBMIT%0A%20%20HOLE%20--%3E%7C%22%E5%90%A6%22%7C%20WAIT%5B%22%E7%BB%A7%E7%BB%AD%E7%AD%89%E6%B4%9E%E5%8F%A3%E9%82%A3%E6%AE%B5%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">直觉类比：重组缓冲像拼图托盘——先到的块按序号摆到各自位置，只等缺的那几块；托盘再满，能交给应用的也只是从左边起连续拼好的那部分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把时间戳选项与 PAWS 写完。不引入纠删码代替重传。流控（接收方缓冲）与拥塞（网络）尚未拆开：下一课先钉重传时机（RTO），窗口随后谈接收方。</p><p>序号 32 位，高速长时间连接要 PAWS 用时间戳防回绕。本课假定窗口内无回绕歧义。</p><p>后课默认：丢失由序号与重传补齐。接收方缓冲有限时发送方必须减速，后课流控窗口。</p><p><span class="marginnote">常见误区：容易以为 TCP 序号按&quot;包&quot;编。它按字节编——一个载 1000 字节的段只占用 1000 个序号坐标，同连接里每个段的序号都是字节位置，不是&quot;第几个报文&quot;。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>字节编号 + 累计 ACK + RTO/快重传 = 可靠前缀。</li><li>Karn 规则处理重传下的 RTT 歧义。</li><li>重传时机（RTO）是下一课；接收窗口与网络拥塞再往后。</li><li>出处：RFC 793；Karn and Partridge, 1987；Kurose and Ross。</li></ul>',8))])}const F=o(C,[["render",d]]);export{f as __pageData,F as default};
